import React from "react";
import { motion } from "framer-motion";
import PageWrapper from "../PageWrapper";

const Home = () => (
  <PageWrapper>
    <div className="flex flex-col items-center justify-center min-h-[80vh] text-center px-6">
      <motion.h1
        initial={{ opacity: 0, y: -20 }}
        animate={{ opacity: 1, y: 0 }}
        transition={{ duration: 0.8 }}
        className="text-5xl font-bold text-blue-700 mb-4"
      >
        Welcome to Your AI Interview Coach 🤖
      </motion.h1>

      <motion.p
        initial={{ opacity: 0, y: 20 }}
        animate={{ opacity: 1, y: 0 }}
        transition={{ delay: 0.3, duration: 0.7 }}
        className="text-gray-600 max-w-xl text-lg mb-8"
      >
        Record or upload your mock interview, get instant feedback, and track your improvement over time.
      </motion.p>

      <motion.a
        href="/interview"
        whileHover={{ scale: 1.1 }}
        whileTap={{ scale: 0.95 }}
        className="bg-blue-600 text-white px-8 py-3 rounded-full font-semibold shadow-md hover:bg-blue-700 transition"
      >
        Start Interview
      </motion.a>
    </div>
  </PageWrapper>
);

export default Home;
